export function getBibleBook(slug: string): BibleBook | undefined {
  return bibleBooks.find((b) => b.slug === slug);
}

export function getAdjacentBooks(slug: string): { prev?: BibleBook; next?: BibleBook } {
  const idx = bibleBooks.findIndex((b) => b.slug === slug);
  if (idx === -1) return {};
  return { prev: bibleBooks[idx - 1], next: bibleBooks[idx + 1] };
}
